def feature_scaler(stat_list, scale = 'max_variance'):

    if scale == 'max_variance':

        if isinstance(stat_list, list) and stat_list.__len__() > 1:

            # Calculating the variances of stats in the stat_list
            var_list = [np.var(stats) for stats in stat_list]

            # Getting the indices of stats with from largest to lowest variance
            I = np.argsort(var_list)[::-1]

            # Scaling each set of statistics based on its ratio between the set
            # with the largest variance
            scaling_factors = np.ones(len(stat_list))
            for i in I[:-1]:
                stats = stat_list[i]
                var_ratio = var_list[i] / var_list[I[-1]]
                scaling_factors[i] = np.sqrt(var_ratio)
                stat_list[i] = stats / scaling_factors[i]

